/// (like `some/path/to/.`) is created (with the dot stripped).
pub fn mkdir(path: &Path, recursive: bool, mode: u32, verbose: bool) -> UResult<()> {
    // Special case to match GNU's behavior:
    // mkdir -p foo/. should work and just create foo/
    // std::fs::create_dir("foo/."); fails in pure Rust
    let path_buf = dir_strip_dot_for_creation(path);

    #[cfg(not(windows))]
    let parent_mode = (!mode::get_umask() & 0o0777) | 0o0300;
    #[cfg(windows)]
    let parent_mode = DEFAULT_PERM;

    let layout = DirectoryLayout::for_creation(path_buf, false, parent_mode, verbose);
    let engine = MkdirEngine { recursive };
    engine.create_dir(&layout)?;
    chmod(layout.target.as_path(), mode)
}

